\label{thm:first-main}
For every cyclic extension $K/F$ of prime degree, every 
quasi-character $\chi_F$ of $F^\times$, and every nontrivial
additive character $\psi_F$ of $F$,
\begin{equation}\label{eq:first-main}
 \Delta_K(\chi_K,\psi_K)
 \prod_{\mu\in S(K/F)}\Delta_F(\mu,\psi_F)
 =
 \prod_{\mu\in S(K/F)}\Delta_F(\mu\chi_F,\psi_F).
\end{equation}

\label{cor:local-gauss-integral-nonzero}
For every quasi-character $\theta$ and every nontrivial additive
character $\psi$, the integral in \eqref{eq:def-delta} is nonzero.

\label{lem:gamma-independent}
The right side of \eqref{eq:def-delta} is independent of the choice of
$\gamma$ satisfying \eqref{eq:admissible-gamma}.

\label{lem:residual-normalization}
Let $\psi_F$ have conductor exponent $n$, and fix a uniformizer
$\varpi_F$.  The formula
\begin{equation}\label{eq:residual-additive-character}
 \bar\psi(\bar x)
 =\psi_F(x\varpi_F^{-n-1}),
 \qquad x\in\mathcal O_F\text{ a lift of }\bar x\in k_F,
\end{equation}
defines a nontrivial additive character of $k_F$, independently of the
choice of the lift $x$.  Define the canonical additive character
$\psi_{\rm can}:k_F\to\mathbf C^\times$ by
\begin{equation}\label{eq:finite-additive-parametrization}
 x\longmapsto
 \exp\left(\frac{2\pi i}{p}
   \operatorname{Tr}_{k_F/\mathbf F_p}(x)\right).
\end{equation}
Then there is a unit $a\in\mathcal O_F^\times$ such that the residual
character attached to $\psi_F^a(x)=\psi_F(ax)$ is $\psi_{\rm can}$.

\label{lem:additive-scale}
For $a\in E^\times$, put $\psi^a(x)=\psi(ax)$.  Then
\begin{equation*}
 \Delta_E(\theta,\psi^a)
 =\theta(a)\Delta_E(\theta,\psi).
\end{equation*}

\label{cor:additive-independence}
For every $a\in F^\times$, the First Main Lemma for $\psi_F$ is
equivalent to the First Main Lemma for $\psi_F^a$.

\label{lem:delta-one}
For every nontrivial additive character $\psi$,
\begin{equation}\label{eq:trivial-local-constant}
 \Delta_E(1,\psi)=1.
\end{equation}

\label{lem:inverse-pair}
Let $\mu$ be a finite-order character of $E^\times$.  Then
\begin{equation}\label{eq:inverse-pair}
 \Delta_E(\mu,\psi)\Delta_E(\mu^{-1},\psi)=\mu(-1).
\end{equation}

\label{cor:S-product-one}
If $K/F$ is cyclic of odd prime degree, then
\begin{equation}\label{eq:S-product-one}
 \prod_{\mu\in S(K/F)}\Delta_F(\mu,\psi_F)=1.
\end{equation}

Define
\begin{equation}\label{eq:error-term}
 \mathcal E_{K/F}(\chi_F)=
 \frac{\Delta_K(\chi_K,\psi_K)
       \prod_{\mu\in S(K/F)}\Delta_F(\mu,\psi_F)}
      {\prod_{\mu\in S(K/F)}\Delta_F(\mu\chi_F,\psi_F)}.
\end{equation}
The denominator is nonzero by
Corollary~\ref{cor:local-gauss-integral-nonzero}, and the First Main
Lemma is the assertion $\mathcal E_{K/F}(\chi_F)=1$.

\label{lem:twist-invariance}
For every $\nu\in S(K/F)$,
\begin{equation}\label{eq:error-twist-invariance}
 \mathcal E_{K/F}(\nu\chi_F)=\mathcal E_{K/F}(\chi_F).
\end{equation}

\label{lem:wild-symmetric-bound}
Assume that $K/F$ is wildly ramified cyclic of prime degree
$\ell=p=\operatorname{char}k_F$, with lower break $t$, and put
$T=t+1$.
For $x\in K$ let $s_j(x)$ be the $j$th elementary symmetric function
of its $p$ conjugates.  If $v_K(x)\ge a$, then, for
$1\le j\le p-1$,
\begin{equation}\label{eq:symmetric-bound}
 v_F(s_j(x))\ge
 \left\lfloor\frac{ja+(p-1)T}{p}\right\rfloor.
\end{equation}
For the last coefficient,
\begin{equation}\label{eq:symmetric-bound-last}
 v_F(s_p(x))=v_F(N_{K/F}x)=v_K(x)\ge a.
\end{equation}

\label{cor:wild-norm-truncation}
Let $q,r\ge0$ and assume
\begin{equation*}
 2q+(p-1)T\ge pr.
\end{equation*}
Then, for every $y\in\mathfrak p_K^q$,
\begin{equation}\label{eq:wild-norm-truncation}
 N_{K/F}(1+y)
 \equiv1+\operatorname{Tr}_{K/F}(y)+N_{K/F}(y)
 \pmod{\mathfrak p_F^r}.
\end{equation}

\label{prop:stable-critical-trace}
Let $K/F$ be totally ramified cyclic of odd prime degree $p$, with
positive lower break $t$.  Choose a uniformizer $\varpi_K$ and a generator $\sigma$ of
$\operatorname{Gal}(K/F)$, put $\varpi_F=N_{K/F}(\varpi_K)$, and define $\lambda$ by
\eqref{eq:critical-ramification-coordinate}.  Suppose $d\ge t+1$
and put
\[
 d'=pd-\frac{p-1}{2}t.
\]
Then
\begin{equation*}
 \frac{\varpi_F}{\varpi_K^p}
 \equiv1\pmod{\mathfrak p_K^{t+1}},
\end{equation*}
\begin{equation*}
 \varpi_K^{2d'}
 \equiv \varpi_F^{2d-t}\varpi_K^t
 \pmod{\mathfrak p_K^{2d'+1}},
\end{equation*}
and
the normalized traces are units with common residue
\begin{equation}\label{eq:stable-critical-trace-residue}
 \overline{\frac{\operatorname{Tr}_{K/F}(\varpi_K^{2d'})}{\varpi_F^{2d}}}
 =\overline{\frac{\operatorname{Tr}_{K/F}(\varpi_K^t)}{\varpi_F^t}}
 =-\lambda^{p-1}.
\end{equation}

\label{cor:additive-conductor}
Let $\psi_K=\psi_F\circ\operatorname{Tr}_{K/F}$.  If $K/F$ is totally ramified of
degree $\ell$, then
\begin{equation}\label{eq:additive-conductor-trace}
 n_K(\psi_K)=\ell n_F(\psi_F)+D_{K/F}.
\end{equation}

\label{prop:pullback-conductor}
Let $K/F$ be ramified cyclic of prime degree $\ell$, with break $t$.
Let $m=m_F(\chi_F)$ and $m'=m_K(\chi_F\circ N_{K/F})$.
\begin{enumerate}[label=(\roman*)]
\item If $m>t+1$, then
\begin{equation}\label{eq:pullback-high}
 m'-1=\psi^{\mathrm H}_{K/F}(m-1).
\end{equation}
\item If $m\leq t$, then $m'=m$.
\item If $m=t+1$, then $m'\leq m$; moreover $m'<m$ if and only if
there is a $\mu\in S(K/F)$ for which
$m_F(\mu\chi_F)<t+1$.
\end{enumerate}

\label{lem:stationary-class-existence}
Let $q=m_E(\theta)>1$, let $n=n_E(\psi)$, choose an integer $M$ and
an element $\Gamma\in E^\times$ such that
\[
 \Gamma\mathcal O_E=\mathfrak p_E^{M+n},
\]
and let $r$ satisfy
\[
 \left\lceil q/2\right\rceil\le r\le q-1.
\]
There is a unique class
\begin{equation*}
 \operatorname{St}_{\Gamma,r}(\theta)
 \in \mathfrak p_E^{M-q}/\mathfrak p_E^{M-r}
\end{equation*}
such that every representative $c$ of this class satisfies
\begin{equation}\label{eq:general-stationary-linearization}
 \theta(1+x)=\psi(cx/\Gamma)
 \qquad(x\in\mathfrak p_E^r).
\end{equation}
Every representative $c$ has exact valuation
\begin{equation}\label{eq:general-stationary-valuation}
 v_E(c)=M-q.
\end{equation}

\label{lem:stable-twist-new}
Let $\nu$ be a quasi-character of $E^\times$.  If
$m_E(\theta)=2d+\varepsilon>1$ and $m_E(\nu)\leq d$, then, for any
representative $\beta$ of the stationary class of $\theta$,
\begin{equation}\label{eq:stable-twist-new}
 \Delta_E(\nu\theta,\psi)=
 \nu(\gamma/\beta)\Delta_E(\theta,\psi).
\end{equation}

\label{thm:HD-lift}
For a finite extension $k'/k$ of degree $f$,
\begin{equation}\label{eq:HD-lift}
 \tau_{k'}(\chi\circ N_{k'/k},\psi\circ\operatorname{Tr}_{k'/k})
 =\tau_k(\chi,\psi)^f.
\end{equation}

\label{prop:affine-pencil-homogeneous}
Under the hypotheses and notation of
Lemma~\ref{lem:affine-pencil}, let $c\in k^\times$.  Then
\begin{align*}
&\frac{
 Q_\psi(ca_0^p,cb_0^p)
 \displaystyle\prod_{j\in\mathbf F_p^\times}Q_\psi(cj\rho,cj\upsilon)}
 {\displaystyle\prod_{j\in\mathbf F_p}
 Q_\psi(c(1+j\rho),c(\sigma+j\upsilon))}
=
\frac{
 Q_\psi(a_0,b_0)
 \displaystyle\prod_{j\in\mathbf F_p^\times}Q_\psi(j\rho,j\upsilon)}
 {\displaystyle\prod_{j\in\mathbf F_p}
 Q_\psi(1+j\rho,\sigma+j\upsilon)}.
\end{align*}
Thus a common nonzero scale  does not change the
normalized affine-pencil quotient.

\label{lem:AS-phase-new}
Let $k$ have characteristic $2$ and let
$\psi_0(x)=(-1)^{\operatorname{Tr}_{k/\mathbf F_2}(x)}$.  Then
\begin{equation}\label{eq:AS-phase}
 \psi_0(c+c^2)=1\qquad(c\in k).
\end{equation}

\label{lem:stationary-depth-norm}
In each of the three cases above,
\begin{align}
 N_{K/F}(U_K^{d'+\varepsilon'})&\subseteq U_F^{d+\varepsilon},
                                                        \label{eq:stationary-depth-first-inclusion}\\
 N_{K/F}(U_K^{m'})&\subseteq U_F^m,             \label{eq:stationary-depth-second-inclusion}\\
 N_{K/F}(U_K^{d'})&\subseteq U_F^d.             \label{eq:stationary-parameter-ambiguity}
\end{align}
The third
inclusion implies that if $b,b'\in\mathcal O_K^\times$ and
$b'\equiv b\pmod{\mathfrak p_K^{d'}}$, then
\begin{equation}\label{eq:norm-of-stationary-class-well-defined}
 N_{K/F}(b')\equiv N_{K/F}(b)\pmod{\mathfrak p_F^d}.
\end{equation}

\label{lem:teichmueller-stationary}
Let $K/F$ be wildly ramified cyclic of prime degree
$p=\operatorname{char}k_F$, with break $t$, and put
$T=t+1$ and $s_0=\lceil T/2\rceil$.  Let $\tau$ be a character of
$F^\times$ of conductor $T$.  For $j\in\mathbf F_p$, let $j_{\mathbf Z}$
be its representative in $\{0,\ldots,p-1\}$, viewed in $F$, and let
$[j]\in\mathcal O_F$ be its Teichmuller lift.  If $A\in F$ satisfies
\[
 \tau(1+x)=\psi_F(Ax)\qquad(x\in\mathfrak p_F^{s_0}),
\]
then
\begin{equation*}
 \psi_F(j_{\mathbf Z}Ax)=\psi_F([j]Ax)
 \qquad(x\in\mathfrak p_F^{s_0}).
\end{equation*}
Thus $[j]A$ and $j_{\mathbf Z}A$ give the same linearization of
$\tau^j$ on $\mathfrak p_F^{s_0}$.  If $p$ is odd, then
\begin{equation}\label{eq:teichmueller-successor-depth}
 [j]-j_{\mathbf Z}\in\mathfrak p_F^{s_0}.
\end{equation}
The Teichmuller lifts satisfy
\begin{equation}\label{eq:teichmueller-polynomials}
 \prod_{j\in\mathbf F_p}(X-[j])=X^p-X,
 \qquad
 \prod_{j\in\mathbf F_p}(X+[j])=X^p+(-1)^pX,
\end{equation}
and
\begin{equation}\label{eq:teichmueller-sum}
 \sum_{j\in\mathbf F_p}[j]=
 \begin{cases}0,&p\text{ odd},\\1,&p=2.\end{cases}
\end{equation}

\label{lem:norm-stationary-representatives}
Let $K/F$ be ramified cyclic of prime degree with break $t$.  Let
$h\in\mathbf Z$, let $0\le s\le t$, and let $c\in F^\times$ have
$v_F(c)=h$.  There is $c_1\in K^\times$ with $v_K(c_1)=h$ such that
\begin{equation}\label{eq:norm-representative-precision}
 c-N_{K/F}(c_1)\in\mathfrak p_F^{h+s}.
\end{equation}

\label{prop:tame-odd-new}
The First Main Lemma holds for a tamely ramified cyclic extension of odd
prime degree.

\label{lem:q0-powers}
One has
\begin{equation}\label{eq:q0-powers}
 q_0^2=\nu(-1),\qquad
 q_0^{p-1}=\nu(-1),\qquad
 q_0^p=q_0\nu(-1).
\end{equation}

\label{lem:odd-break-line-normalization}
A generator $\tau$ of $S(K/F)$ can be chosen so that
\begin{equation}\label{eq:odd-tau-last-layer}
 \tau(1+\varpi_F^t\widetilde z)
 =\psi_0(\lambda^{-p}z)\qquad(z\in k).
\end{equation}
Put
\begin{equation}\label{eq:odd-eta0-normalization}
 \eta_0=\lambda^{-p}.
\end{equation}
If $T$ is odd, the Hasse function of $\tau$ with critical element
$\delta_\tau=\varpi_F^{(T-1)/2}$ has quadratic coefficient $\eta_0$.

\label{prop:odd-phase-cancel}
Retain the minimal-conductor choice of $\chi_F$.
The residual factors satisfy
\begin{equation}\label{eq:Rodd}
 \mathcal R_{\mathrm{odd}}:=
 \frac{\Delta_{3,K}(\chi_K)
       \prod_{j\in\mathbf F_p^\times}\Delta_{3,F}(\tau^j)}
      {\prod_{j\in\mathbf F_p}\Delta_{3,F}(\tau^j\chi_F)}=1.
\end{equation}

\label{lem:parameter-ratios}
One has
\begin{equation}\label{eq:parameter-ratios}
 N_{K/F}(u+j)=(\mathcal N+j)z_j,
 \qquad
 N_{K/F}(\mathcal N-u)=\left(\prod_{j\in\mathbf F_p}(\mathcal N+j)\right)z_0.
\end{equation}

\label{lem:correction-depth}
One has
\begin{equation}\label{eq:correction-depths}
\begin{aligned}
 z_j-1&\in
 \mathfrak p_F^{\left\lfloor(|a|+(p-1)T)/p\right\rfloor}
 \subseteq\mathfrak p_F^{s_0} &&(j\ne0),\\
 z_0-1&\in
 \mathfrak p_F^{\left\lfloor(p-1)(T+|a|)/p\right\rfloor}
 \subseteq\mathfrak p_F^{\lceil m/2\rceil}.
\end{aligned}
\end{equation}
Thus $z_j-1$ lies in the linearization domain of $\tau$ and
$z_0-1$ lies in the linearization domain of $\chi_F$.

\label{prop:correction-linearization}
With $A$, $\mathcal N$, $z_0$, and $z_j$ defined by
\eqref{eq:A-u} and \eqref{eq:correction-units},
\begin{equation*}
 \chi_F(z_0)=\psi_F\bigl(A\mathcal N(z_0-1)\bigr),
 \qquad
 \tau^j(z_j)=\psi_F\bigl(Aj(z_j-1)\bigr)
 \quad(j\ne0).
\end{equation*}

\label{prop:exact-odd-assembly}
The error quotient \eqref{eq:error-term}
\[
 \mathcal E_{K/F}(\chi_F)
 =\mathcal R_{\mathrm{odd}}\,\psi_F(-AX),
\]
where
\begin{equation}\label{eq:X-def}
 X=\operatorname{Tr}_{K/F}(u)+\mathcal N(z_0-1)+\sum_{j\ne0}j(z_j-1).
\end{equation}

\label{prop:X-closed}
The element $X$ in \eqref{eq:X-def} satisfies  
\begin{equation}\label{eq:X-closed}
 X=\frac{pB}{1-\mathcal N^{p-1}}.
\end{equation}

\label{prop:X-depth}
Retain the minimal-conductor choice of $\chi_F$.
One has
\begin{equation}\label{eq:X-depth-final}
 X\in\mathfrak p_F^T,
 \qquad \psi_F(A\mathfrak p_F^T)=1.
\end{equation}
If $\operatorname{char}F=p$, then $X=0$.  In all cases
$\psi_F(-AX)=1$.

\label{lem:quad-X}
Put $s=\operatorname{Tr}_{K/F}(u)$ and
$X=s+\mathcal N(z_0-1)+(z_1-1)$.  Then
\begin{equation}\label{eq:quad-zxy}
 z_0-1=-\frac{s}{1+\mathcal N},\qquad
 z_1-1=\frac{s}{1+\mathcal N},\qquad
 X=\frac{2s}{1+\mathcal N}.
\end{equation}

\label{lem:quadratic-graded-trace}
Let $K/F$ be wildly ramified quadratic and let
$T=v_K(\mathfrak D_{K/F})=t+1$.  If $r\ge0$ and $r+T$ is odd,
trace induces a $k$-linear isomorphism
\[
 \operatorname{Tr}_{K/F}:\mathfrak p_K^r/\mathfrak p_K^{r+1}
 \xrightarrow{\ \sim\ }
 \mathfrak p_F^{(r+T-1)/2}/\mathfrak p_F^{(r+T+1)/2}.
\]
In particular:
\begin{enumerate}[label=(\alph*)]
\item If $T$ is odd and $d_\tau=(T-1)/2$, then
$v_F(2)=d_\tau$.  For every $w\in\mathcal O_K^\times$ and every lift
$\widetilde{\bar w}\in\mathcal O_F$ of its residue,
\begin{equation}\label{eq:quadratic-unit-trace-class}
 \operatorname{Tr}(w)\equiv2\widetilde{\bar w}\pmod{\mathfrak p_F^{d_\tau+1}}.
\end{equation}
\item If $m=2d+1>T$ and $r=m-T$, then trace identifies
$\mathfrak p_K^r/\mathfrak p_K^{r+1}$ with $\mathfrak p_F^d/\mathfrak p_F^{d+1}$.
\end{enumerate}

\label{lem:normalized-refinement}
Let $h:k\to\mathbf C^\times$ be unimodular and satisfy
$h(r+s)=h(r)h(s)\psi_0(rs)$.
Multiplying $h$ by an additive character gives a unimodular function
$\mathfrak q:k\to\mathbf C^\times$ such that
\begin{equation}\label{eq:q-refinement}
 \mathfrak q(r+s)=\mathfrak q(r)\mathfrak q(s)\psi_0(rs),
 \qquad
 \mathfrak q(r^2)=\mathfrak q(r).
\end{equation}
Every other function with the same polar character is uniquely
\begin{equation}\label{eq:q-linear-family}
 h_\lambda(z)=\mathfrak q(z)\psi_0(\lambda z)
 \qquad(\lambda\in k).
\end{equation}
Write
\begin{equation}\label{eq:quadratic-normalized-sum}
 H(\lambda)=\operatorname{ph}\!\left(\sum_{z\in k}h_\lambda(z)\right),
 \qquad H_0=H(0).
\end{equation}
We have
\begin{equation}\label{eq:q-phase-translation}
 H(\lambda)=H_0\overline{\mathfrak q(\lambda)},
 \qquad H_0^2=\mathfrak q(1),
 \qquad \mathfrak q(r)^2=\psi_0(r).
\end{equation}

\label{prop:quadratic-residual-quotient}
Retain the setup and notation of
Proposition~\ref{prop:quadratic-critical-functions}.  Then
\begin{equation}\label{eq:quadratic-raw-Hasse-quotient}
\begin{aligned}
 \mathcal R_{\mathrm{even}}
 &:=\frac{\Delta_{3,K}(\chi_K)\Delta_{3,F}(\tau)}
      {\Delta_{3,F}(\chi_F)\Delta_{3,F}(\tau\chi_F)}\\
 &=\begin{cases}
  1,&m<T\text{ or }m\text{ even},\\[1mm]
  h_\gamma(1)^{-1},&m>T,\ m\text{ odd},\\[1mm]
  h_{\gamma_1+1}\!\left(\dfrac{\rho}{1+\rho}\right),
     &m=T,\ T\text{ odd}.
 \end{cases}
\end{aligned}
\end{equation}

\label{lem:quadratic-correction-depth}
The correction units in \eqref{eq:quad-corrections} satisfy
\begin{equation}\label{eq:quadratic-correction-depth-bound}
 v_F(z_0-1)=v_F(z_1-1)
 \ge\left\lfloor\frac{T+|a|}{2}\right\rfloor.
\end{equation}

\label{prop:quadratic-correction-values}
Retain the setup and notation of
Proposition~\ref{prop:quadratic-critical-functions}.   One has
\begin{equation}\label{eq:quadratic-correction-values}
\begin{aligned}
 &\bigl(\psi_F(A\mathcal N(z_0-1))\chi_F(z_0)^{-1},\,
        \psi_F(A(z_1-1))\tau(z_1)^{-1}\bigr)\\
 &\qquad=\begin{cases}
 (1,1),&m<T\text{ or }m\text{ even},\\[1mm]
 (h_\gamma(1),1),&m>T,\ m\text{ odd},\\[1mm]
 \left(h_\gamma\!\left(\dfrac{\rho^2}{1+\rho^2}\right),\,
       h_{\gamma_0}\!\left(\dfrac{\rho}{1+\rho^2}\right)\right),
       &m=T,\ T\text{ odd}.
 \end{cases}
\end{aligned}
\end{equation}

\label{prop:quadratic-complete-assembly}
Retain the minimal-conductor choice of $\chi_F$.
With $X$ from Lemma~\ref{lem:quad-X},
$\mathcal R_{\mathrm{even}}$ from
\eqref{eq:quadratic-raw-Hasse-quotient}, and $\rho=\bar u$ when $m=T$,
the error quotient satisfies
\begin{equation}\label{eq:quadratic-assembly}
\begin{aligned}
 \mathcal E_{K/F}(\chi_F)
 &=\mathcal R_{\mathrm{even}}\,\psi_F(-AX)\\[-1mm]
 &\quad\times\begin{cases}
  1,&m<T\text{ or }m\text{ even},\\[1mm]
  h_\gamma(1),&m>T,\ m\text{ odd},\\[1mm]
  h_\gamma\!\left(\dfrac{\rho^2}{1+\rho^2}\right)
  h_{\gamma_0}\!\left(\dfrac{\rho}{1+\rho^2}\right),
    &m=T,\ T\text{ odd}.
 \end{cases}
\end{aligned}
\end{equation}

\label{prop:quadratic-norm-trace-phase}
Retain the minimal-conductor choice of $\chi_F$ and $X$ from
Lemma~\ref{lem:quad-X}.
If $\operatorname{char}F=2$, then $X=0$.
If $\operatorname{char}F=0$ and either $m\ne T$ or $T$ is even, then
$X\in\mathfrak p_F^T$.
With $\rho=\bar u$ when $m=T$, one has
\begin{equation}\label{eq:quadratic-norm-trace-phase}
 \psi_F(-AX)=
 \begin{cases}
  1,&m\ne T\text{ or }T\text{ even},\\[1mm]
  \psi_0\!\left(\dfrac{\rho}{1+\rho^2}\right),&m=T,\ T\text{ odd}.
 \end{cases}
\end{equation}
